/* UK Study Plus · French
   Year 8: KS3 Modern Foreign Languages (National Curriculum in England), as taught in Dubai British-curriculum schools from Year 7.
   Year 10: Pearson Edexcel International GCSE French (4FR1), the five themes: A Home and abroad, B Education and employment,
   C Personal life and relationships, D The world around us, E Social activities, fitness and health, plus a grammar topic for the top grades.
   Every topic has a Verb lab (learn.verbs → study/lang.js) and pronunciation help (learn.pron); French text has 🔊 audio buttons.
   Helpers: m() multiple choice (first option is right; options are shuffled on screen), tf(), tx() typed. Pools are append-only. */
(function(U){
const m = (d, q, right, wrong, x) => ({ d, k:"mcq", q, o:[right].concat(wrong), a:0, x });
const tf = (d, q, a, x) => ({ d, k:"tf", q, a, x });
const tx = (d, q, a, x, prefix) => Object.assign({ d, k:"text", q, a:[].concat(a), x }, prefix ? { prefix } : {});
const ex = (q, steps, a) => ({ q, steps, a });
const T = o => ({ id:o.id, title:o.title, strand:o.strand, bbc:o.bbc, yt:o.yt, learn:{ ideas:o.ideas, example:o.example, more:o.more || [], fun:o.fun, trick:o.trick, verbs:o.verbs, pron:o.pron }, tasks:o.tasks, pool:o.pool || [] });

/* ============================== YEAR 8 · KS3 ============================== */
const K = "KS3 · French";
U.y8french = { name:"French", year:8, icon:"Fr", colour:"#1F4E9C", lang:"fr", verbLevel:"ks3",
  blurb:"KS3 French with audio: me and my family, school, free time, town and holidays, and a verb lab", topics:[
 T({ id:"me", title:"All about me and my family", strand:K + " · Identity and relationships", bbc:"KS3 French family and describing people", yt:"KS3 French describing family and personality adjectives",
   ideas:["Introduce yourself: Je m'appelle… J'ai treize ans. J'habite à Dubaï. Je suis britannique / émirien(ne) / indien(ne).",
     "Family: mon père, ma mère, mon frère, ma sœur, mes grands-parents, mon oncle, ma tante, mon cousin, ma cousine. Je suis fils unique / fille unique (only child).",
     "Possessives agree with the noun owned: mon / ma / mes (my), ton / ta / tes (your), son / sa / ses (his OR her). Sa sœur = his sister or her sister.",
     "Adjectives agree: add -e for feminine, -s for plural. Patterns: sportif → sportive, heureux → heureuse, gentil → gentille, beau → belle.",
     "Most adjectives go after the noun (un chat noir); BAGS adjectives (Beauty, Age, Goodness, Size) go before: une petite maison, un bon ami.",
     "Hair and eyes use avoir: J'ai les cheveux bruns et les yeux verts. Height and personality use être: Elle est grande et drôle.",
     "Relationships: je m'entends bien avec… (I get on well with), je me dispute avec… (I argue with), parce qu'il est… (because he is…)."],
   example:"Describe your sister in French: she is 15, tall, funny and has long black hair.\nMa sœur s'appelle Lina.\nElle a quinze ans.\nElle est grande et drôle.\nElle a les cheveux longs et noirs.\nJe m'entends bien avec elle parce qu'elle est gentille.",
   more:[ ex("Translate: 'My brothers are lazy but kind.'", ["Plural noun → mes frères.","Être with ils → sont.","Adjectives agree with masculine plural → paresseux (already ends in x), gentils."], "Mes frères sont paresseux mais gentils."),
     ex("Translate: 'His mother is very sporty.' (Omar's mother)", ["Possessive agrees with mère (feminine) → sa.","Sportif → sportive for a feminine noun."], "Sa mère est très sportive.") ],
   trick:"Hair and eyes are things you HAVE (avoir); being tall or funny is what you ARE (être).",
   fun:"French has two words for 'you': tu for one friend and vous for adults or groups. Using tu with your teacher would sound rude!",
   verbs:["etre","avoir","sappeler","habiter"],
   pron:["Cheveux: 'shuh-vuh'. Yeux (eyes): 'zyuh', in les yeux you hear 'lay zyuh'.","Grand ('groh(n)') → grande ('groh(n)d'): the feminine makes you hear the d.","Gentil ('zhoh(n)-tee') → gentille ('zhoh(n)-tee-yuh')."],
   tasks:[ m(1, "What does 'ma tante' mean?", "my aunt", ["my uncle", "my cousin", "my grandmother"], "Ma tante = my aunt. Mon oncle = my uncle, mon cousin / ma cousine = my cousin, ma grand-mère = my grandmother."),
     m(1, "Choose the correct possessive: '___ grands-parents habitent en Inde.'", "Mes", ["Mon", "Ma", "Me"], "Grands-parents is plural, so 'my' = mes."),
     m(1, "How do you say 'I have green eyes'?", "J'ai les yeux verts.", ["Je suis les yeux verts.", "J'ai verts yeux.", "J'ai les yeux vert."], "Eyes use avoir: j'ai les yeux… The colour comes after and agrees with yeux (masculine plural): verts."),
     m(2, "Choose the correct adjective: 'Ma mère est très ___.' (sporty)", "sportive", ["sportif", "sportifs", "sportives"], "Mère is feminine singular: sportif → sportive."),
     m(2, "'Son frère est grand.' Ali is speaking about Sara. What does it mean?", "Her brother is tall.", ["His brother is tall.", "My brother is tall.", "Their brother is tall."], "Son agrees with frère (masculine), not with the owner. Talking about Sara, son frère = her brother."),
     m(2, "Choose the correct form: 'Mes cousines sont ___.' (happy)", "heureuses", ["heureux", "heureuse", "heureuxes"], "Adjectives in -eux become -euse in the feminine; feminine plural = heureuses."),
     tx(2, "Complete: 'Je m'entends bien ___ ma sœur.' (with)", ["avec"], "S'entendre bien avec = to get on well with. Je m'entends bien avec ma sœur."),
     m(3, "Which sentence is correct?", "J'ai un petit chien noir.", ["J'ai un chien petit noir.", "J'ai une petite chien noir.", "J'ai un noir petit chien."], "Petit is a BAGS adjective (size) so it goes before; colours go after. Chien is masculine: un petit chien noir."),
     m(3, "Translate: 'My grandmother is old but very active.'", "Ma grand-mère est vieille mais très active.", ["Ma grand-mère est vieux mais très actif.", "Mon grand-mère est vieille mais très active.", "Ma grand-mère est vieille mais très actif."], "Feminine forms: vieux → vieille, actif → active. Grand-mère takes ma."),
     m(3, "Which reply gives an opinion and a reason?", "Je me dispute avec mon frère parce qu'il est égoïste.", ["Mon frère s'appelle Karim.", "J'ai un frère.", "Mon frère a dix ans."], "Je me dispute avec… (I argue with) + parce qu'il est égoïste (because he is selfish) gives an opinion with a justification.") ],
   pool:[ m(1, "What is 'fils unique'?", "an only child (boy)", ["a unique son", "one brother", "the oldest son"], "Fils unique / fille unique = only child (boy / girl)."),
     m(1, "How do you say 'I am 13'?", "J'ai treize ans.", ["Je suis treize ans.", "J'ai treize.", "Je treize ans."], "Age uses avoir: j'ai treize ans."),
     m(2, "Choose the correct form: 'Elle a les cheveux ___.' (short)", "courts", ["courte", "court", "courtes"], "Les cheveux is masculine plural, so the adjective is courts."),
     m(2, "Which adjective is irregular in the feminine?", "beau → belle", ["grand → grande", "petit → petite", "noir → noire"], "Beau → belle (and vieux → vieille, nouveau → nouvelle)."),
     m(3, "Translate: 'We get on well with our cousins.'", "Nous nous entendons bien avec nos cousins.", ["Nous entendons bien nos cousins.", "Nous nous entendons bien avec notre cousins.", "On s'entend bien avec nos cousin."], "S'entendre is reflexive: nous nous entendons. Plural of notre = nos."),
     m(3, "Choose the correct form: 'Mes sœurs sont ___.' (kind)", "gentilles", ["gentils", "gentille", "gentiles"], "Gentil doubles the l in the feminine: gentille → gentilles.") ] }),

 T({ id:"school", title:"School life and opinions", strand:K + " · School", bbc:"KS3 French school subjects and opinions", yt:"KS3 French school subjects opinions parce que",
   ideas:["Subjects: les maths, l'anglais, le français, l'arabe, les sciences, l'histoire, la géographie, l'informatique, le dessin (art), l'EPS (PE), la musique.",
     "Opinions: j'aime, j'adore, je préfère, je n'aime pas, je déteste + le / la / les + subject. Ma matière préférée, c'est… (My favourite subject is…).",
     "Reasons: parce que / car c'est + adjective: intéressant, facile, utile (useful), ennuyeux (boring), difficile, nul (rubbish). Le prof est sympa / strict.",
     "Time: à huit heures (at 8), à dix heures et quart (10:15), à midi (at noon). Les cours commencent à… (lessons start at…) et finissent à…",
     "Comparatives: plus … que (more … than), moins … que (less … than), aussi … que (as … as): Les maths sont plus difficiles que l'anglais.",
     "Rules: il faut + infinitive (you must): il faut porter un uniforme. Il est interdit de + infinitive (it is forbidden to): il est interdit de manger en classe.",
     "Develop answers: add a second opinion with mais (but), a time phrase and a past or future sentence."],
   example:"Give your opinion on maths and history with reasons.\nJ'adore les maths parce que c'est logique et le prof est sympa.\nPar contre, je n'aime pas l'histoire car c'est ennuyeux.\nÀ mon avis, les maths sont plus utiles que l'histoire.",
   more:[ ex("Translate: 'At my school, you must wear a uniform.'", ["Dans mon école = at my school.","Il faut + infinitive = you must.","Porter = to wear."], "Dans mon école, il faut porter un uniforme."),
     ex("Say: 'Lessons start at 7:45.'", ["Lessons = les cours, start = commencent (ils form).","7:45 = huit heures moins le quart."], "Les cours commencent à huit heures moins le quart.") ],
   trick:"PARCE QUE is 'because' and turns a basic answer into a good one: always give a reason.",
   fun:"French secondary school years count DOWN: pupils start collège in 'sixième' (6e) at 11 and finish in 'troisième' (3e) at 14.",
   verbs:["aimer","finir","devoir","ecrire"],
   pron:["Informatique: 'a(n)-for-ma-teek'. EPS: 'uh-pay-ess'.","Ennuyeux: 'oh(n)-nwee-yuh'.","Parce que: 'parss-kuh', said as one word."],
   tasks:[ m(1, "What is 'l'informatique'?", "computing / ICT", ["information", "maths", "science"], "L'informatique = computing / ICT. Une information is a piece of news."),
     m(1, "What does 'ennuyeux' mean?", "boring", ["easy", "useful", "fun"], "Ennuyeux = boring. Facile = easy, utile = useful, amusant = fun."),
     m(1, "How do you say 'My favourite subject is art'?", "Ma matière préférée, c'est le dessin.", ["Mon matière préféré est dessin.", "J'aime matière le dessin.", "Ma préférée matière est le dessin."], "Matière is feminine: ma matière préférée. Art = le dessin (or les arts plastiques)."),
     m(2, "'Les cours commencent à huit heures moins le quart.' What time do lessons start?", "7:45", ["8:15", "8:45", "7:15"], "Moins le quart = quarter to. Huit heures moins le quart = 7:45."),
     m(2, "Choose the correct comparison: 'Science is easier than French.'", "Les sciences sont plus faciles que le français.", ["Les sciences sont plus facile que le français.", "Les sciences est plus faciles que le français.", "Les sciences sont moins faciles que le français."], "Plus … que = more … than. Les sciences is plural, so sont and faciles."),
     m(2, "What does 'Il est interdit d'utiliser son portable' mean?", "It is forbidden to use your phone.", ["You must use your phone.", "You can use your phone.", "It is useful to use your phone."], "Il est interdit de + infinitive = it is forbidden to. Le portable = mobile phone."),
     tx(2, "Complete: 'Il ___ porter un uniforme.' (you must)", ["faut"], "Il faut + infinitive = you must / it is necessary to."),
     m(3, "Which answer is the most developed?", "J'aime les sciences car c'est intéressant, mais l'année prochaine je vais étudier l'informatique.", ["J'aime les sciences.", "Les sciences.", "C'est intéressant."], "It has an opinion, a reason (car), a contrast (mais) and a future time frame (je vais étudier)."),
     m(3, "Translate: 'Yesterday I had a maths test.'", "Hier, j'ai eu un contrôle de maths.", ["Hier, j'ai un contrôle de maths.", "Hier, je suis eu un contrôle de maths.", "Demain, j'ai eu un contrôle de maths."], "Passé composé of avoir: j'ai eu (sounds like 'zhay ew'). Un contrôle = a test."),
     m(3, "Choose the correct form: 'Nous ___ l'école à quinze heures.' (finir)", "finissons", ["finons", "finissez", "finisons"], "Regular -ir verbs: nous finissons.") ],
   pool:[ m(1, "What is 'l'EPS'?", "PE", ["English", "science", "history"], "L'EPS = éducation physique et sportive = PE."),
     m(1, "What does 'utile' mean?", "useful", ["useless", "easy", "difficult"], "Utile = useful. Inutile = useless."),
     m(2, "Choose: 'Le français est ___ difficile ___ l'anglais.' (as … as)", "aussi … que", ["plus … de", "moins … de", "aussi … de"], "Aussi … que = as … as."),
     m(2, "Translate: 'The teacher is strict.'", "Le prof est sévère.", ["Le prof est sympa.", "La prof est strict.", "Le prof a sévère."], "Sévère (or strict) = strict. Sympa = nice."),
     m(3, "Which sentence uses the near future correctly?", "L'année prochaine, je vais apprendre l'espagnol.", ["L'année prochaine, j'ai appris l'espagnol.", "L'année prochaine, je vais apprends l'espagnol.", "L'année dernière, je vais apprendre l'espagnol."], "Prochaine = next → aller + infinitive: je vais apprendre."),
     m(3, "What does 'Par contre' mean?", "On the other hand", ["Because", "Therefore", "Afterwards"], "Par contre = on the other hand / however. Useful to contrast opinions.") ] }),

 T({ id:"freetime", title:"Free time, sport and technology", strand:K + " · Free time", bbc:"KS3 French hobbies and free time", yt:"KS3 French hobbies jouer faire weather near future",
   ideas:["Jouer à + sport / game: je joue au foot, au basket, aux jeux vidéo. Jouer de + instrument: je joue du piano, de la guitare.",
     "Faire de + activity: je fais du vélo, de la natation, de l'escalade (climbing), des randonnées.",
     "Opinion + infinitive: j'aime regarder des séries, je préfère lire, je n'aime pas danser.",
     "Frequency: tous les jours (every day), souvent (often), de temps en temps (from time to time), une fois par semaine, ne… jamais (never).",
     "Technology: j'utilise mon portable pour envoyer des messages, regarder des vidéos et écouter de la musique. Je passe deux heures par jour sur Internet.",
     "Weather: il fait beau / chaud / froid, il pleut, il neige, il y a du soleil / du vent.",
     "Near future = aller + infinitive: ce week-end, je vais faire du shopping."],
   example:"Say what you do when it is hot and what you will do this weekend.\nQuand il fait chaud, je fais de la natation.\nJe joue aussi au tennis une fois par semaine.\nCe week-end, je vais aller au centre commercial avec mes amis.",
   more:[ ex("Translate: 'I never play video games.'", ["Never = ne … jamais around the verb.","Jouer à + les jeux vidéo → aux jeux vidéo."], "Je ne joue jamais aux jeux vidéo."),
     ex("Translate: 'I use my phone to watch videos.'", ["J'utilise mon portable.","Pour + infinitive = in order to: pour regarder des vidéos."], "J'utilise mon portable pour regarder des vidéos.") ],
   trick:"Sport → jouer À (au foot). Music → jouer DE (du piano). Ball games you play AT; instruments you play OF.",
   fun:"Ski Dubai lets you faire du ski indoors when it's 45 °C outside!",
   verbs:["jouer","faire","aimer","lire","sortir"],
   pron:["Escalade: 'es-ka-lad'. Randonnée: 'roh(n)-do-nay'.","Il neige: 'eel nezh'.","Jeux vidéo: 'zhuh vee-day-oh'."],
   tasks:[ m(1, "How do you say 'I play basketball'?", "Je joue au basket.", ["Je joue du basket.", "Je fais au basket.", "Je joue à le basket."], "Sport uses jouer à; à + le = au."),
     m(1, "What does 'il neige' mean?", "It's snowing.", ["It's raining.", "It's windy.", "It's sunny."], "Il neige = it's snowing. Il pleut = it's raining."),
     m(1, "What does 'de temps en temps' mean?", "from time to time", ["every day", "never", "always"], "De temps en temps = from time to time / sometimes."),
     m(2, "Choose the correct form: 'Mon frère joue ___ batterie.' (drums)", "de la", ["à la", "du", "au"], "Instruments use jouer de. Batterie is feminine: de la batterie."),
     m(2, "Choose the correct form: 'Je fais ___ escalade.'", "de l'", ["du", "de la", "à l'"], "Escalade starts with a vowel: faire de l'escalade."),
     m(2, "Translate: 'I never watch TV.'", "Je ne regarde jamais la télé.", ["Je regarde jamais la télé.", "Je ne regarde pas jamais la télé.", "Je ne jamais regarde la télé."], "Ne … jamais goes around the verb like ne … pas."),
     tx(2, "Complete with the near future: 'Ce soir, je ___ regarder un film.'", ["vais"], "Near future = aller + infinitive. Je vais regarder = I am going to watch."),
     m(3, "Which sentence is correct?", "Quand il pleut, je reste à la maison et je lis.", ["Quand il pleut, je reste à la maison et je lire.", "Quand il fait pleut, je reste à la maison.", "Quand il pleut, je resté à la maison."], "Il pleut (not il fait pleut). After je, use the present form: je lis."),
     m(3, "Translate: 'I spend three hours a day on my phone.'", "Je passe trois heures par jour sur mon portable.", ["Je dépense trois heures par jour sur mon portable.", "Je passe trois heures pour jour sur mon portable.", "Je passe trois heures par jours sur mon portable."], "Passer du temps = to spend time (dépenser is for money). Par jour = per day."),
     m(3, "Which sentence uses three time frames?", "Hier j'ai joué au foot, aujourd'hui je fais du vélo et demain je vais nager.", ["Hier je joue au foot et demain je nage.", "Je joue au foot et je fais du vélo.", "Demain j'ai nagé."], "Past (j'ai joué), present (je fais) and near future (je vais nager).") ],
   pool:[ m(1, "What is 'la natation'?", "swimming", ["cycling", "climbing", "running"], "La natation = swimming."),
     m(1, "How do you say 'It's hot'?", "Il fait chaud.", ["Il est chaud.", "Il a chaud.", "C'est chaud temps."], "Weather uses il fait: il fait chaud."),
     m(2, "Choose: 'Nous jouons ___ jeux vidéo.'", "aux", ["au", "des", "à les"], "Jeux vidéo is plural: à + les = aux."),
     m(2, "What does 'J'envoie des messages' mean?", "I send messages.", ["I read messages.", "I write letters.", "I delete messages."], "Envoyer = to send. J'envoie des messages = I send messages."),
     m(3, "Translate: 'Last weekend I went cycling.'", "Le week-end dernier, j'ai fait du vélo.", ["Le week-end dernier, je fais du vélo.", "Le week-end dernier, je suis fait du vélo.", "Le week-end prochain, j'ai fait du vélo."], "Faire takes avoir in the past: j'ai fait. Dernier = last."),
     m(3, "Which is the best answer to 'Qu'est-ce que tu fais le week-end ?'", "Le samedi, je joue au foot et le dimanche, je vais au cinéma avec ma famille.", ["Le foot.", "Oui, le week-end.", "J'aime."], "A full answer with days, two activities and who with.") ] }),

 T({ id:"town", title:"My town and holidays", strand:K + " · Home, town and travel", bbc:"KS3 French town and holidays past tense", yt:"KS3 French holidays passé composé avoir être",
   ideas:["Places: le parc, le marché, la plage, la piscine, la gare, le centre commercial, la mosquée, le musée, la bibliothèque (library).",
     "Il y a… (there is / are), il n'y a pas de… (there isn't any). Dans ma ville, il y a beaucoup de magasins mais il n'y a pas de cinéma.",
     "À + le = au, à + la = à la, à + l' = à l', à + les = aux: je vais au parc, à la piscine, aux magasins.",
     "Countries: en France (feminine), au Maroc (masculine), aux États-Unis (plural), à Paris (city).",
     "Passé composé: avoir + past participle for most verbs (j'ai visité, j'ai mangé). Être for movement verbs (je suis allé(e), je suis resté(e), je suis parti(e)).",
     "Imperfect for descriptions in the past: c'était génial (it was great), il faisait chaud (it was hot), il y avait beaucoup de monde (there were lots of people).",
     "Transport: en avion (by plane), en voiture, en train, en bus, à pied (on foot)."],
   example:"Describe a past holiday.\nL'été dernier, je suis allé en France avec ma famille.\nNous avons voyagé en avion.\nJ'ai visité la tour Eiffel et j'ai mangé des croissants.\nC'était génial parce qu'il faisait beau.",
   more:[ ex("Translate: 'There isn't a museum in my town.'", ["There isn't = il n'y a pas.","After a negative, un becomes de: pas de musée."], "Il n'y a pas de musée dans ma ville."),
     ex("Translate: 'We stayed in a hotel near the beach.'", ["Rester takes être: nous sommes restés.","Près de + la plage."], "Nous sommes restés dans un hôtel près de la plage.") ],
   trick:"Mrs Van der Tramp verbs take être in the past: Monter, Rester, Sortir, Venir, Aller, Naître, Descendre, Entrer, Rentrer, Tomber, Retourner, Arriver, Mourir, Partir.",
   fun:"France is the most visited country in the world, with around 90 million tourists a year.",
   verbs:["aller","prendre","partir","voir","acheter"],
   pron:["C'était: 'say-teh'. Il faisait: 'eel fuh-zeh'.","Je suis allé and je suis allée sound the same: 'zhuh swee za-lay'.","Bibliothèque: 'bee-blee-oh-tek'."],
   tasks:[ m(1, "What is 'la bibliothèque'?", "the library", ["the bookshop", "the museum", "the station"], "La bibliothèque = library. La librairie = bookshop (a false friend!)."),
     m(1, "How do you say 'by plane'?", "en avion", ["à avion", "par l'avion", "en l'avion"], "Most transport uses en: en avion, en voiture, en train. But à pied (on foot)."),
     m(1, "Choose the correct form: 'Je vais ___ piscine.'", "à la", ["au", "aux", "à le"], "Piscine is feminine: à la piscine."),
     m(2, "Choose the correct form: 'L'année dernière, je ___ allé au Maroc.'", "suis", ["ai", "vais", "étais"], "Aller takes être in the passé composé: je suis allé."),
     m(2, "Choose the correct form: 'Nous ___ visité un musée.'", "avons", ["sommes", "allons", "avez"], "Visiter takes avoir: nous avons visité."),
     m(2, "What does 'C'était génial' mean?", "It was great.", ["It is great.", "It will be great.", "It was boring."], "C'était is the imperfect of c'est: it was."),
     tx(2, "Give the past participle of 'manger'.", ["mangé", "mange"], "-er verbs: drop -er, add -é: manger → mangé."),
     m(3, "Choose the correct sentence: 'My sister arrived late.'", "Ma sœur est arrivée en retard.", ["Ma sœur a arrivé en retard.", "Ma sœur est arrivé en retard.", "Ma sœur est arriver en retard."], "Arriver takes être, and the participle agrees with a feminine subject: arrivée."),
     m(3, "Which is the best description of a past holiday?", "Il faisait chaud et c'était très relaxant.", ["Il fait chaud et c'est relaxant.", "Il va faire chaud.", "Il a fait chaud demain."], "Descriptions in the past use the imperfect: il faisait, c'était."),
     m(3, "Translate: 'Next year, I am going to go to Spain.'", "L'année prochaine, je vais aller en Espagne.", ["L'année prochaine, je suis allé en Espagne.", "L'année dernière, je vais aller en Espagne.", "L'année prochaine, je vais aller au Espagne."], "Near future: je vais aller. Espagne is feminine: en Espagne.") ],
   pool:[ m(1, "What is 'la gare'?", "the train station", ["the garage", "the airport", "the bus stop"], "La gare = train station. L'aéroport = airport."),
     m(1, "What does 'à pied' mean?", "on foot", ["by bike", "by car", "by bus"], "À pied = on foot."),
     m(2, "Choose: 'J'habite ___ États-Unis.'", "aux", ["en", "au", "à"], "Plural countries take aux: aux États-Unis."),
     m(2, "Which verb takes être in the passé composé?", "partir", ["manger", "visiter", "acheter"], "Partir is a Mrs Van der Tramp verb: je suis parti(e)."),
     m(3, "Translate: 'There were lots of tourists.'", "Il y avait beaucoup de touristes.", ["Il y a beaucoup des touristes.", "Il était beaucoup de touristes.", "Il y avait beaucoup des touristes."], "Il y avait = there was / were (imperfect). Beaucoup de, never beaucoup des."),
     m(3, "Choose the correct form: 'Elles ___ restées à l'hôtel.'", "sont", ["ont", "est", "sommes"], "Rester takes être; elles sont restées (feminine plural agreement).") ] }),

 T({ id:"verbs", title:"Verb lab: present, past and future", strand:K + " · Grammar", bbc:"KS3 French verbs present perfect near future", yt:"KS3 French verbs present tense passé composé near future explained",
   ideas:["Present tense of regular verbs: -er (parler: je parle, nous parlons), -ir (finir: je finis, nous finissons), -re (vendre: je vends, nous vendons).",
     "Learn the big four irregular verbs by heart: être, avoir, aller, faire.",
     "Near future: aller + infinitive: je vais jouer (I am going to play).",
     "Passé composé: avoir / être + past participle. Participles: -er → -é (joué), -ir → -i (fini), -re → -u (vendu). Irregular: fait, eu, été, vu, pris, bu, lu, mis.",
     "Être verbs (movement and change) agree with the subject: elle est partie, ils sont arrivés. Reflexive verbs also take être: je me suis levé(e).",
     "Imperfect for 'was …ing', 'used to' and descriptions: take the nous form, remove -ons, add -ais, -ais, -ait, -ions, -iez, -aient: nous jouons → je jouais. Only être is irregular: j'étais.",
     "Negatives wrap the verb: je ne joue pas; in the past they wrap the helping verb: je n'ai pas joué."],
   example:"Say the same idea in four tenses: 'play tennis'.\nPresent: je joue au tennis (I play tennis).\nPast: j'ai joué au tennis (I played tennis).\nImperfect: je jouais au tennis (I used to play tennis).\nNear future: je vais jouer au tennis (I am going to play tennis).",
   more:[ ex("Form the imperfect of 'faire' with 'je'.", ["Nous form: nous faisons.","Remove -ons: fais-.","Add -ais: je faisais."], "je faisais"),
     ex("Make negative: 'Elle est sortie.'", ["Ne … pas goes around the helping verb (est).","Ne → n' before a vowel."], "Elle n'est pas sortie.") ],
   trick:"Imperfect = 'nous minus ons, plus ais'. The only exception is être (j'étais).",
   fun:"Je jouais, tu jouais, il jouait and ils jouaient all sound the same: 'zhoo-eh'!",
   verbs:["etre","avoir","aller","faire","parler","finir","vendre","prendre","vouloir","pouvoir","devoir","venir"],
   pron:["The imperfect endings -ais, -ait and -aient all sound like 'eh'.","J'ai joué ('zhay zhoo-ay') vs je jouais ('zhuh zhoo-eh'): listen for the final sound.","Je vais ('zhuh veh') starts the near future: listen for it."],
   tasks:[ m(1, "What is the past participle of 'finir'?", "fini", ["finé", "finu", "finit"], "-ir verbs: drop -ir, add -i: fini."),
     m(1, "Choose the near future: 'I am going to eat.'", "Je vais manger.", ["Je mange.", "J'ai mangé.", "Je vais mange."], "Aller + infinitive: je vais manger."),
     m(1, "Choose the correct form of être: 'Ils ___ français.'", "sont", ["ont", "est", "sommes"], "Être: ils sont. (Ils ont = they have.)"),
     m(2, "What is the past participle of 'prendre'?", "pris", ["prendu", "prené", "prit"], "Prendre → pris: j'ai pris le bus."),
     m(2, "Choose the correct form: 'Hier, elle ___ partie à huit heures.'", "est", ["a", "était", "va"], "Partir takes être: elle est partie."),
     m(2, "Which is the imperfect of 'jouer' with 'je'?", "je jouais", ["j'ai joué", "je jouerai", "je joue"], "Nous jouons → jou- + -ais = je jouais (I used to play / I was playing)."),
     tx(2, "Give the imperfect of être with 'c'' (it was): c'______", ["était", "etait"], "C'était = it was. Être is the only irregular imperfect stem (ét-)."),
     m(3, "Make negative: 'J'ai vu le film.'", "Je n'ai pas vu le film.", ["Je n'ai vu pas le film.", "Je ne vu pas le film.", "J'ai ne pas vu le film."], "In the passé composé, ne … pas goes around avoir: je n'ai pas vu."),
     m(3, "Choose the correct form: 'Nous nous ___ levés tôt.'", "sommes", ["avons", "sont", "êtes"], "Reflexive verbs take être: nous nous sommes levés."),
     m(3, "Which sentence correctly mixes tenses?", "Quand j'étais petit, je jouais au foot, mais maintenant je fais de la natation.", ["Quand j'ai été petit, j'ai joué au foot souvent.", "Quand je suis petit, je jouais au foot.", "Quand j'étais petit, je vais jouer au foot."], "Imperfect for 'when I was little' and 'used to', present for 'now'.") ],
   pool:[ m(1, "What is the past participle of 'vendre'?", "vendu", ["vendé", "vendi", "vend"], "-re verbs: drop -re, add -u: vendu."),
     m(1, "Choose the correct form: 'Nous ___ au parc.' (aller)", "allons", ["allez", "vont", "vais"], "Aller: nous allons."),
     m(2, "Which verb takes être in the passé composé?", "arriver", ["regarder", "finir", "boire"], "Arriver (Mrs Van der Tramp): je suis arrivé(e)."),
     m(2, "What does 'je faisais' mean?", "I was doing / I used to do", ["I did", "I will do", "I would do"], "Faisais is the imperfect: an ongoing or repeated past action."),
     m(3, "Translate: 'They (girls) went out.'", "Elles sont sorties.", ["Elles ont sorti.", "Elles sont sortis.", "Elles sont sortie."], "Sortir takes être; feminine plural agreement: sorties."),
     m(3, "Form the imperfect of 'avoir' with 'nous'.", "nous avions", ["nous avons", "nous avaient", "nous avons eu"], "Nous avons → av- + -ions = nous avions.") ] })
]};

/* ============================== YEAR 10 · EDEXCEL INTERNATIONAL GCSE 4FR1 ============================== */
const E = "Edexcel IGCSE 4FR1";
U.y10french = { name:"French", year:10, icon:"Fr", colour:"#1F4E9C", lang:"fr", verbLevel:"igcse",
  blurb:"Edexcel IGCSE French (4FR1) with audio: the five themes plus the tenses and structures for top grades", topics:[
 T({ id:"home", title:"Home and abroad: town, holidays and travel", strand:E + " · Theme A Home and abroad", bbc:"GCSE French holidays and travel", yt:"IGCSE French holidays travel town region revision",
   ideas:["Town and region: J'habite dans une grande ville / un petit village au bord de la mer / à la campagne. Ce qui me plaît, c'est… (What I like is…).",
     "Advantages and disadvantages: L'avantage, c'est qu'il y a beaucoup de choses à faire. L'inconvénient, c'est qu'il y a trop de circulation (traffic).",
     "Holidays in the past: je suis allé(e), nous avons logé dans un hôtel (stayed), j'ai fait de la plongée (diving), c'était inoubliable (unforgettable).",
     "Pronoun y = there (replaces à + place): Je vais à Paris → J'y vais. Je suis allé en France → J'y suis allé.",
     "Ideal holiday with the conditional: Si j'étais riche, j'irais aux Maldives et je logerais dans un hôtel de luxe.",
     "Travel problems: le vol a été annulé (the flight was cancelled), j'ai perdu mon passeport, il y avait des embouteillages (traffic jams).",
     "Customs and festivals: Pendant le ramadan, on jeûne pendant la journée. Pour l'Aïd, ma famille se réunit et on offre des cadeaux."],
   example:"Answer: 'Parle-moi de tes dernières vacances.' (Tell me about your last holiday.)\nL'été dernier, je suis allée en Suisse avec ma famille.\nNous y sommes allés en avion et nous avons logé dans un chalet.\nJ'ai fait des randonnées et c'était magnifique, mais il faisait assez froid.\nL'année prochaine, j'aimerais visiter le Canada.",
   more:[ ex("Replace the place with y: 'Je vais au marché le samedi.'", ["Au marché = à + place, so replace it with y.","Y goes before the verb."], "J'y vais le samedi."),
     ex("Translate: 'If I won the lottery, I would travel around the world.'", ["Si + imperfect: si je gagnais au loto.","Then conditional: je ferais le tour du monde."], "Si je gagnais au loto, je ferais le tour du monde.") ],
   trick:"Si + imperfect → conditional: 'Si j'avais… je ferais…' Never put the conditional straight after si.",
   fun:"French uses 'le week-end' and 'le parking' but Quebec French prefers 'la fin de semaine' and 'le stationnement'!",
   verbs:["aller","partir","prendre","venir","voir","acheter"],
   pron:["Inoubliable: 'ee-noo-blee-ah-bluh'.","Embouteillages: 'oh(n)-boo-tay-yazh'.","J'irais ('zhee-reh', I would go) and j'irai ('zhee-ray', I will go) sound slightly different."],
   tasks:[ m(1, "What does 'la circulation' mean?", "traffic", ["circle", "the town centre", "pollution"], "La circulation = traffic. Embouteillages = traffic jams."),
     m(1, "What does 'nous avons logé dans un hôtel' mean?", "we stayed in a hotel", ["we booked a hotel", "we built a hotel", "we left the hotel"], "Loger = to stay (accommodation)."),
     m(2, "Replace with y: 'Je vais à la plage.'", "J'y vais.", ["Je vais y.", "Y je vais.", "J'en vais."], "Y replaces à + place and goes before the verb: j'y vais."),
     m(2, "Which phrase gives a disadvantage?", "L'inconvénient, c'est qu'il y a trop de bruit.", ["Ce qui me plaît, c'est la plage.", "L'avantage, c'est le parc.", "J'adore mon quartier."], "L'inconvénient = the disadvantage. Trop de bruit = too much noise."),
     m(2, "What does 'Le vol a été annulé' mean?", "The flight was cancelled.", ["The flight was late.", "The flight was full.", "The flight was cheap."], "Annulé = cancelled. En retard = late."),
     m(2, "Choose the conditional: 'I would like to visit Japan.'", "J'aimerais visiter le Japon.", ["J'aimerai visiter le Japon.", "J'aime visiter le Japon.", "J'ai aimé visiter le Japon."], "Conditional = future stem + imperfect endings: j'aimerais. J'aimerai (no s) is the future."),
     tx(3, "Complete: 'Si j'étais riche, j'___ aux Maldives.' (aller, conditional)", ["irais"], "Si + imperfect (j'étais) → conditional: j'irais (from the future stem ir-)."),
     m(3, "Translate: 'We went there by train.'", "Nous y sommes allés en train.", ["Nous sommes allés y en train.", "Nous y avons allé en train.", "Y nous sommes allés en train."], "Y goes before the helping verb: nous y sommes allés."),
     m(3, "Which sentence uses the imperfect and the passé composé correctly?", "Il faisait beau quand nous sommes arrivés.", ["Il a fait beau quand nous arrivions toujours.", "Il fait beau quand nous sommes arrivés hier.", "Il faisait beau quand nous arrivons."], "Imperfect for the background (il faisait beau), passé composé for the completed event (nous sommes arrivés)."),
     m(3, "What does 'Pendant le ramadan, on jeûne pendant la journée' mean?", "During Ramadan, people fast during the day.", ["During Ramadan, we eat all day.", "After Ramadan, we celebrate.", "During Ramadan, we travel."], "Jeûner = to fast. On = we / people in general.") ],
   pool:[ m(1, "What is 'à la campagne'?", "in the countryside", ["in the city", "at the seaside", "in the mountains"], "À la campagne = in the countryside. Au bord de la mer = at the seaside."),
     m(2, "What does 'inoubliable' mean?", "unforgettable", ["unbelievable", "unpleasant", "uncomfortable"], "Inoubliable = unforgettable (in- + oublier = to forget)."),
     m(2, "Translate: 'I lost my passport.'", "J'ai perdu mon passeport.", ["Je suis perdu mon passeport.", "J'ai perdre mon passeport.", "Je perds mon passeport hier."], "Perdre → perdu, with avoir."),
     m(3, "Choose the correct order: 'I have never been there.'", "Je n'y suis jamais allé.", ["Je ne suis jamais allé y.", "Je n'y jamais suis allé.", "J'y ne suis jamais allé."], "Ne + y + helping verb + jamais + participle."),
     m(3, "Which sentence is grammatically correct?", "Si j'avais le temps, je voyagerais plus.", ["Si j'aurais le temps, je voyagerais plus.", "Si j'ai le temps, je voyagerais plus.", "Si j'avais le temps, je voyagerai plus."], "Si + imperfect, then conditional (voyagerais)."),
     m(3, "What does 'Ce qui me plaît, c'est le calme' mean?", "What I like is the peace and quiet.", ["What annoys me is the calm.", "It is calm here.", "I like it when it's busy."], "Ce qui me plaît = what pleases me / what I like.") ] }),

 T({ id:"education", title:"Education and employment: school, jobs and future plans", strand:E + " · Theme B Education and employment", bbc:"GCSE French school and future plans", yt:"IGCSE French future plans jobs school revision",
   ideas:["School life: J'étudie neuf matières. Ma matière préférée est la physique car le prof explique bien. Les journées sont longues et on a trop de devoirs.",
     "Depuis + present = for / since: J'apprends le français depuis cinq ans (I have been learning French for five years).",
     "Future tense: infinitive (drop -e for -re verbs) + -ai, -as, -a, -ons, -ez, -ont: je travaillerai, je finirai, j'apprendrai. Irregular stems: ir- (aller), fer- (faire), ser- (être), aur- (avoir), pourr- (pouvoir), voudr- (vouloir), devr- (devoir), viendr- (venir).",
     "Plans: Après mes examens, je voudrais aller au lycée / à l'université. J'ai l'intention de… (I intend to), j'espère + infinitive (I hope to).",
     "Jobs: médecin, ingénieur(e), avocat(e) (lawyer), infirmier / infirmière (nurse), professeur, informaticien(ne). In French there is no 'a' before a job: je voudrais être médecin.",
     "Work experience in the past: J'ai fait un stage dans un bureau. J'ai dû répondre au téléphone. C'était fatigant mais enrichissant.",
     "Quand + future: Quand je serai plus âgé(e), je travaillerai à l'étranger (abroad)."],
   example:"Answer: 'Qu'est-ce que tu voudrais faire à l'avenir ?'\nJe voudrais devenir ingénieur parce que j'adore les maths et la physique.\nD'abord, j'irai à l'université à Londres.\nQuand j'aurai mon diplôme, j'espère travailler à l'étranger, peut-être au Canada.",
   more:[ ex("Translate: 'I have been learning Arabic for three years.'", ["French uses depuis + PRESENT for something still going on.","J'apprends l'arabe + depuis trois ans."], "J'apprends l'arabe depuis trois ans."),
     ex("Translate: 'When I am older, I will be a doctor.'", ["After quand about the future, French uses the FUTURE: quand je serai.","Main verb also future: je serai médecin (no 'un')."], "Quand je serai plus âgé(e), je serai médecin.") ],
   trick:"Future endings = present of avoir (ai, as, a, ons, ez, ont) stuck on the infinitive.",
   fun:"Le bac (baccalauréat) is the French school-leaving exam, a bit like A levels. Its philosophy essay has been compulsory for over 200 years.",
   verbs:["devoir","pouvoir","vouloir","venir","ecrire","savoir"],
   pron:["Ingénieur: 'a(n)-zhay-nyuhr'. Infirmière: 'a(n)-feer-myair'.","Je travaillerai: 'zhuh tra-va-yuh-ray'.","Depuis: 'duh-pwee'."],
   tasks:[ m(1, "What is 'un avocat' (job)?", "a lawyer", ["a doctor", "an avocado seller", "a nurse"], "Un avocat / une avocate = a lawyer (avocat is also an avocado!)."),
     m(1, "How do you say 'I would like to be a nurse' (girl speaking)?", "Je voudrais être infirmière.", ["Je voudrais être une infirmière.", "Je veux est infirmière.", "Je voudrais infirmière être."], "No article before jobs after être: je voudrais être infirmière."),
     m(2, "Translate: 'I have been learning French for four years.'", "J'apprends le français depuis quatre ans.", ["J'ai appris le français depuis quatre ans.", "J'apprends le français pour quatre ans.", "J'apprendrai le français depuis quatre ans."], "Depuis + present tense for an action still going on."),
     m(2, "Which is the future of 'aller' with 'je'?", "j'irai", ["j'allerai", "je vais", "j'irais"], "Aller has the irregular future stem ir-: j'irai (I will go). J'irais = I would go."),
     m(2, "What does 'J'ai fait un stage' mean?", "I did work experience.", ["I went on stage.", "I did a course.", "I had a holiday."], "Un stage = work experience / internship."),
     m(2, "Choose the future: 'Nous ___ nos examens en juin.' (passer)", "passerons", ["passons", "passerions", "avons passé"], "Future = infinitive + -ons: nous passerons."),
     tx(3, "Complete with the future: 'Quand je ___ plus âgé, je voyagerai.' (être)", ["serai"], "After quand about the future, French uses the future tense: quand je serai."),
     m(3, "Which sentence is correct?", "Quand j'aurai dix-huit ans, j'apprendrai à conduire.", ["Quand j'ai dix-huit ans, j'apprendrai à conduire.", "Quand j'aurai dix-huit ans, j'apprends à conduire.", "Quand j'aurais dix-huit ans, j'apprendrai à conduire."], "Both verbs are in the future: quand j'aurai… j'apprendrai."),
     m(3, "What does 'J'ai dû répondre au téléphone' mean?", "I had to answer the phone.", ["I should answer the phone.", "I wanted to answer the phone.", "I could answer the phone."], "J'ai dû = passé composé of devoir: I had to."),
     m(3, "Which phrase means 'I intend to'?", "J'ai l'intention de", ["J'ai envie de", "J'ai besoin de", "J'ai peur de"], "Avoir l'intention de = to intend to. Envie de = feel like, besoin de = need, peur de = afraid of.") ],
   pool:[ m(1, "What does 'à l'étranger' mean?", "abroad", ["strange", "a stranger", "outside"], "À l'étranger = abroad."),
     m(2, "What is the future stem of 'faire'?", "fer-", ["fair-", "fais-", "fait-"], "Je ferai, tu feras, il fera…"),
     m(2, "What does 'enrichissant' mean?", "rewarding", ["rich", "boring", "tiring"], "Enrichissant = rewarding / enriching. Fatigant = tiring."),
     m(3, "Translate: 'I hope to go to university.'", "J'espère aller à l'université.", ["J'espère de aller à l'université.", "J'espère que aller à l'université.", "J'espère à aller à l'université."], "Espérer + infinitive with no preposition."),
     m(3, "Choose the correct future: 'Ils ___ venir.' (pouvoir)", "pourront", ["pouvront", "pouvoiront", "peuvent"], "Pouvoir has the future stem pourr-: ils pourront."),
     m(3, "Which is NOT a future tense form?", "je voudrais", ["je voudrai", "j'aurai", "je serai"], "Je voudrais (with s) is conditional: I would like.") ] }),

 T({ id:"personal", title:"Personal life and relationships: family, friends and daily life", strand:E + " · Theme C Personal life and relationships", bbc:"GCSE French relationships family friends", yt:"IGCSE French relationships family friends relative pronouns",
   ideas:["Relationships: je m'entends bien avec (get on well with), je me dispute avec (argue with), il m'énerve (he annoys me), elle me soutient (she supports me).",
     "A good friend: Un bon ami est quelqu'un qui est fidèle, qui m'écoute et sur qui je peux compter (who I can count on).",
     "Relative pronouns: qui (who / which, subject), que (whom / which, object), dont (of which / whose), où (where): Le livre que je lis… La ville où j'habite…",
     "Home: J'habite dans un appartement au troisième étage. Dans ma chambre, il y a un lit, un bureau et une armoire. Je partage ma chambre avec mon frère.",
     "Daily routine with reflexive verbs: je me réveille, je me lève, je me douche, je m'habille, je me couche. Past: je me suis levé(e).",
     "Imperfect for childhood: Quand j'étais petit(e), j'habitais en Égypte et je jouais dans le jardin.",
     "Role models: Mon modèle est… parce qu'il / elle a travaillé dur et aide les autres."],
   example:"Answer: 'Décris ta relation avec ta famille.'\nJe m'entends bien avec ma mère parce qu'elle me soutient toujours.\nPar contre, je me dispute parfois avec mon petit frère qui m'énerve quand il prend mes affaires.\nQuand j'étais petite, nous étions plus proches.",
   more:[ ex("Join with qui: 'J'ai une amie. Elle s'appelle Nour.'", ["Elle is the subject of the second sentence, so use qui.","Qui replaces elle."], "J'ai une amie qui s'appelle Nour."),
     ex("Join with que: 'C'est le film. J'ai vu le film hier.'", ["Le film is the object of j'ai vu, so use que.","Que + subject + verb."], "C'est le film que j'ai vu hier.") ],
   trick:"QUI is followed by a verb (qui m'écoute); QUE is followed by a subject (que je lis).",
   fun:"'Mon pote' is casual French for 'my mate'. 'Ma meilleure amie' = my best friend (girl).",
   verbs:["selever","sappeler","dire","mettre","dormir"],
   pron:["Je me dispute: 'zhuh muh dees-pewt'.","Fidèle: 'fee-del'. Quelqu'un: 'kel-ka(n)'.","Armoire: 'ar-mwahr'."],
   tasks:[ m(1, "What does 'je me dispute avec mon frère' mean?", "I argue with my brother.", ["I get on with my brother.", "I play with my brother.", "I talk to my brother."], "Se disputer = to argue."),
     m(1, "What is 'une armoire'?", "a wardrobe", ["an armchair", "a desk", "a bed"], "Une armoire = wardrobe. Un fauteuil = armchair, un bureau = desk."),
     m(2, "Choose the relative pronoun: 'C'est une amie ___ m'écoute.'", "qui", ["que", "dont", "où"], "Followed by a verb (m'écoute) and replacing the subject: qui."),
     m(2, "Choose the relative pronoun: 'Le livre ___ je lis est passionnant.'", "que", ["qui", "dont", "où"], "Followed by a subject (je): que."),
     m(2, "Choose the relative pronoun: 'La ville ___ j'habite est moderne.'", "où", ["que", "qui", "dont"], "Où = where (place)."),
     m(2, "Choose the correct form: 'Ce matin, je me ___ levé à six heures.'", "suis", ["ai", "est", "suisse"], "Reflexive verbs take être in the passé composé: je me suis levé."),
     tx(3, "Complete with the imperfect: 'Quand j'étais petit, j'___ en Égypte.' (habiter)", ["habitais"], "Imperfect for childhood: nous habitons → habit- + -ais = j'habitais."),
     m(3, "Translate: 'She is someone I can count on.'", "C'est quelqu'un sur qui je peux compter.", ["C'est quelqu'un que je peux compter.", "Elle est quelqu'un qui je peux compter.", "C'est quelqu'un où je peux compter."], "Compter sur = to count on, so the preposition sur comes before qui."),
     m(3, "Which sentence is correct?", "Ma sœur et moi, nous nous sommes disputées hier.", ["Ma sœur et moi, nous avons disputé hier.", "Ma sœur et moi, nous sommes disputées hier.", "Ma sœur et moi, nous nous avons disputées hier."], "Reflexive verb (se disputer) → être + reflexive pronoun, with agreement for two girls."),
     m(3, "What does 'Il m'énerve' mean?", "He annoys me.", ["He helps me.", "He inspires me.", "He ignores me."], "Énerver = to annoy. Il m'énerve = he gets on my nerves.") ],
   pool:[ m(1, "What does 'je partage ma chambre' mean?", "I share my bedroom.", ["I tidy my bedroom.", "I paint my bedroom.", "I leave my bedroom."], "Partager = to share."),
     m(2, "What does 'fidèle' mean?", "loyal", ["funny", "faithful to a religion only", "famous"], "Fidèle = loyal / faithful."),
     m(2, "Choose: 'C'est l'ami ___ je t'ai parlé.' (whom I told you about)", "dont", ["que", "qui", "où"], "Parler de → dont: the friend I spoke to you about."),
     m(3, "Translate: 'When I was little, we used to live in a house.'", "Quand j'étais petit, nous habitions dans une maison.", ["Quand j'ai été petit, nous avons habité dans une maison.", "Quand j'étais petit, nous habitons dans une maison.", "Quand je suis petit, nous habitions une maison."], "Imperfect for both: j'étais, nous habitions."),
     m(3, "Which is the correct negative?", "Je ne me lève jamais tôt le week-end.", ["Je me ne lève jamais tôt le week-end.", "Je ne lève me jamais tôt.", "Je ne me jamais lève tôt."], "Ne + reflexive pronoun + verb + jamais."),
     m(3, "What is a 'modèle' in 'Mon modèle est ma grand-mère'?", "a role model", ["a fashion model", "a toy", "an example sentence"], "Un modèle (here) = role model.") ] }),

 T({ id:"world", title:"The world around us: environment, technology and media", strand:E + " · Theme D The world around us", bbc:"GCSE French environment and technology", yt:"IGCSE French environment technology il faut on devrait",
   ideas:["Environment problems: la pollution, le réchauffement climatique (global warming), les déchets (waste), la déforestation, la sécheresse (drought), les espèces menacées.",
     "Solutions: il faut + infinitive (we must), on devrait + infinitive (we should), il est important de… On devrait recycler, économiser l'eau, utiliser les transports en commun.",
     "What I do: Je trie mes déchets (I sort my rubbish), j'éteins la lumière (I switch off the light), je prends des douches courtes.",
     "Technology: les réseaux sociaux (social media) permettent de rester en contact, mais il y a des dangers comme le harcèlement en ligne (cyberbullying).",
     "Opinions with 'Je pense que / À mon avis / Je trouve que' + clause. Balance: d'un côté… de l'autre côté… (on one hand… on the other hand…).",
     "Higher: il faut que + subjunctive: il faut que nous fassions des efforts (we must make an effort). Subjunctive of faire: que je fasse, que nous fassions.",
     "Media: Je regarde des séries en streaming, je lis les actualités (news) sur mon portable."],
   example:"Answer: 'Qu'est-ce que tu fais pour protéger l'environnement ?'\nÀ la maison, je trie mes déchets et j'éteins toujours la lumière.\nLe week-end dernier, j'ai participé à un nettoyage de la plage.\nÀ l'avenir, on devrait utiliser plus d'énergie solaire, surtout aux Émirats où il y a beaucoup de soleil.",
   more:[ ex("Translate: 'We should use public transport.'", ["Should = on devrait (conditional of devoir).","Utiliser + les transports en commun."], "On devrait utiliser les transports en commun."),
     ex("Translate: 'Social media can be dangerous.'", ["Les réseaux sociaux (plural) → peuvent (pouvoir, ils form).","Dangereux agrees: masculine plural dangereux."], "Les réseaux sociaux peuvent être dangereux.") ],
   trick:"Il faut / on doit = we must. On devrait = we should. Swap them in to sound more advanced.",
   fun:"Recycling in French is 'le recyclage', and a bottle bank is 'un conteneur à verre'.",
   verbs:["devoir","pouvoir","faire","mettre","savoir"],
   pron:["Réchauffement: 'ray-shohf-moh(n)'.","Déchets: 'day-sheh'.","Réseaux sociaux: 'ray-zoh so-syoh'."],
   tasks:[ m(1, "What is 'le réchauffement climatique'?", "global warming", ["climate zone", "heating", "weather forecast"], "Le réchauffement climatique = global warming."),
     m(1, "What are 'les déchets'?", "waste / rubbish", ["deserts", "dangers", "droughts"], "Les déchets = waste. La sécheresse = drought."),
     m(2, "Choose the best translation of 'We should save water.'", "On devrait économiser l'eau.", ["On doit économiser de l'eau hier.", "On devra économiser l'eau.", "On a économisé l'eau."], "Should = conditional of devoir: on devrait."),
     m(2, "What does 'le harcèlement en ligne' mean?", "cyberbullying", ["online shopping", "online gaming", "a long queue"], "Le harcèlement = bullying / harassment; en ligne = online."),
     m(2, "What does 'J'éteins la lumière' mean?", "I switch off the light.", ["I switch on the light.", "I buy a lamp.", "I break the light."], "Éteindre = to switch off. Allumer = to switch on."),
     m(2, "Which phrase means 'on the one hand'?", "d'un côté", ["par contre", "cependant", "en plus"], "D'un côté… de l'autre côté… = on the one hand… on the other hand…"),
     tx(3, "Complete with the subjunctive: 'Il faut que nous ___ des efforts.' (faire)", ["fassions"], "Il faut que + subjunctive. Faire → que nous fassions."),
     m(3, "Translate: 'Last week I took part in a beach clean-up.'", "La semaine dernière, j'ai participé à un nettoyage de la plage.", ["La semaine dernière, je participe à un nettoyage de la plage.", "La semaine prochaine, j'ai participé à un nettoyage.", "La semaine dernière, je suis participé à un nettoyage."], "Participer takes avoir: j'ai participé à…"),
     m(3, "Which sentence gives a balanced view?", "Les réseaux sociaux sont utiles pour rester en contact, mais ils peuvent causer de l'anxiété.", ["Les réseaux sociaux sont nuls.", "J'adore les réseaux sociaux.", "Il y a des réseaux sociaux."], "An advantage, mais, and a disadvantage = balanced."),
     m(3, "What does 'les espèces menacées' mean?", "endangered species", ["dangerous spices", "threatened jobs", "special offers"], "Une espèce = a species; menacée = threatened / endangered.") ],
   pool:[ m(1, "What does 'recycler' mean?", "to recycle", ["to cycle", "to reuse a bike", "to reduce"], "Recycler = to recycle."),
     m(2, "What does 'les actualités' mean?", "the news", ["current affairs only on TV", "activities", "updates to an app"], "Les actualités / les infos = the news."),
     m(2, "Choose: 'À mon avis, il est important ___ protéger la planète.'", "de", ["à", "que", "pour"], "Il est important de + infinitive."),
     m(3, "Which is the subjunctive of 'aller' with 'je'?", "que j'aille", ["que je vais", "que j'irai", "que j'allais"], "Aller → que j'aille, que nous allions."),
     m(3, "Translate: 'If everyone recycled, the planet would be cleaner.'", "Si tout le monde recyclait, la planète serait plus propre.", ["Si tout le monde recycle, la planète serait plus propre.", "Si tout le monde recyclerait, la planète serait plus propre.", "Si tout le monde recyclait, la planète sera plus propre."], "Si + imperfect (recyclait) → conditional (serait)."),
     m(3, "What does 'la sécheresse' mean?", "drought", ["safety", "dryer", "dry cleaning"], "La sécheresse = drought (sec = dry).") ] }),

 T({ id:"social", title:"Social activities, fitness and health", strand:E + " · Theme E Social activities, fitness and health", bbc:"GCSE French healthy living", yt:"IGCSE French healthy living sport food negatives revision",
   ideas:["Healthy living: pour être en forme (to be fit), il faut manger équilibré (a balanced diet), dormir huit heures et faire du sport régulièrement.",
     "Unhealthy habits: je mange trop de sucreries (sweets), je passe trop de temps devant les écrans (screens), je ne bois pas assez d'eau.",
     "Negatives: ne… plus (no longer), ne… jamais (never), ne… rien (nothing), ne… personne (nobody): Je ne mange plus de fast-food.",
     "Venir de + infinitive = to have just: je viens de courir (I have just run). Avant de + infinitive (before …ing). Après avoir / être + participle (after having…): après avoir mangé.",
     "Illness: j'ai mal à la tête (headache), au ventre (stomach), aux dents (teeth). J'ai de la fièvre. Je suis enrhumé(e) (I have a cold).",
     "Special occasions: Pour mon anniversaire, j'ai organisé une fête. Pour l'Aïd, nous rendons visite à la famille et nous mangeons des pâtisseries.",
     "Food and eating out: Je voudrais réserver une table pour quatre personnes. Comme entrée… comme plat principal… comme dessert…"],
   example:"Answer: 'Que fais-tu pour rester en forme ?'\nJe fais de la natation trois fois par semaine et je mange beaucoup de fruits et de légumes.\nAvant, je mangeais trop de chocolat, mais je n'en mange plus.\nLe mois prochain, je vais participer à un semi-marathon.",
   more:[ ex("Translate: 'After having eaten, I went for a walk.'", ["Après avoir + past participle: après avoir mangé.","Faire une promenade → j'ai fait une promenade."], "Après avoir mangé, j'ai fait une promenade."),
     ex("Translate: 'I have a stomach ache.'", ["Avoir mal à + body part.","À + le ventre = au ventre."], "J'ai mal au ventre.") ],
   trick:"Avoir mal À: au (masculine), à la (feminine), à l' (vowel), aux (plural). J'ai mal aux dents!",
   fun:"In French you don't 'catch' a cold: you are 'enrhumé(e)', from le rhume (a cold).",
   verbs:["manger","boire","dormir","faire","venir"],
   pron:["Équilibré: 'ay-kee-lee-bray'.","J'ai mal à la tête: 'zhay mal a la tet'.","Enrhumé: 'oh(n)-rew-may'."],
   tasks:[ m(1, "What does 'J'ai mal à la tête' mean?", "I have a headache.", ["I have a sore throat.", "My head is big.", "I am tired."], "Avoir mal à + body part = to have a pain in. La tête = head."),
     m(1, "What are 'les sucreries'?", "sweets", ["sugar cane", "sugary drinks only", "desserts in a restaurant"], "Les sucreries = sweets / sugary things."),
     m(2, "Translate: 'I no longer eat fast food.'", "Je ne mange plus de fast-food.", ["Je ne mange pas plus de fast-food.", "Je mange plus de fast-food.", "Je ne mange jamais du fast-food plus."], "Ne… plus = no longer. After a negative, du becomes de."),
     m(2, "What does 'Je viens de courir' mean?", "I have just been running.", ["I am coming to run.", "I will run.", "I come from running club."], "Venir de + infinitive = to have just done."),
     m(2, "Choose: 'J'ai mal ___ dents.'", "aux", ["au", "à la", "à les"], "Les dents is plural: à + les = aux."),
     m(2, "What does 'manger équilibré' mean?", "to eat a balanced diet", ["to eat a lot", "to eat quickly", "to skip meals"], "Équilibré = balanced."),
     tx(3, "Complete: 'Avant ___ me coucher, je lis.' (before)", ["de"], "Avant de + infinitive = before …ing: avant de me coucher."),
     m(3, "Translate: 'After having played football, I was tired.'", "Après avoir joué au foot, j'étais fatigué.", ["Après jouer au foot, j'étais fatigué.", "Après avoir jouer au foot, j'étais fatigué.", "Après avoir joué au foot, je suis fatigué hier."], "Après avoir + past participle (joué). Imperfect for the state: j'étais fatigué."),
     m(3, "Which sentence is correct?", "Je ne vois personne au parc.", ["Je vois ne personne au parc.", "Je ne vois pas personne au parc.", "Je ne personne vois au parc."], "Ne… personne (nobody) wraps the verb; never add pas as well."),
     m(3, "Which phrase is best for booking a table?", "Je voudrais réserver une table pour quatre personnes.", ["Je veux une table maintenant.", "Donnez une table.", "Table quatre."], "Je voudrais (conditional) is polite.") ],
   pool:[ m(1, "What does 'être en forme' mean?", "to be fit / healthy", ["to be in a form", "to fill a form", "to be shaped"], "Être en forme = to be in good shape."),
     m(2, "What does 'Je suis enrhumé' mean?", "I have a cold.", ["I am hungry.", "I am hot.", "I am injured."], "Enrhumé(e) = having a cold."),
     m(2, "What does 'je ne fais rien' mean?", "I do nothing.", ["I do everything.", "I never do it.", "I don't do it any more."], "Ne… rien = nothing."),
     m(3, "Translate: 'I used to eat too many sweets.'", "Je mangeais trop de sucreries.", ["J'ai mangé trop des sucreries.", "Je mange trop de sucreries.", "Je mangerai trop de sucreries."], "Used to = imperfect: je mangeais. Trop de (never trop des)."),
     m(3, "Choose: 'Après être ___, elle s'est reposée.' (arriver)", "arrivée", ["arrivé", "arriver", "arrivant"], "Après être + participle, agreeing with elle: arrivée."),
     m(3, "Translate: 'I don't drink enough water.'", "Je ne bois pas assez d'eau.", ["Je ne bois pas assez de l'eau.", "Je bois pas assez eau.", "Je ne bois assez pas d'eau."], "Assez de (d') + noun, with no article.") ] }),

 T({ id:"grammar", title:"Grammar for top grades: tenses and structures", strand:E + " · Grammar (all papers)", bbc:"GCSE French tenses", yt:"IGCSE French grade 9 grammar tenses pluperfect conditional subjunctive",
   ideas:["Use a range of tenses: present, passé composé, imperfect, future, conditional, and at the top grades the pluperfect (j'avais fini = I had finished).",
     "Pluperfect = imperfect of avoir / être + past participle: j'avais mangé, j'étais allé(e).",
     "Conditional = future stem + imperfect endings: je ferais, je serais, j'aurais. Si + imperfect → conditional.",
     "Object pronouns go before the verb: le / la / les (it / them), lui / leur (to him / her / them): Je le regarde. Je lui parle. In the passé composé: je l'ai vu.",
     "En replaces de + noun: Tu as des frères ? Oui, j'en ai deux. Y replaces à + place: J'y vais.",
     "Subjunctive after il faut que, bien que (although), pour que (so that), avant que: Bien qu'il soit difficile, j'aime le français.",
     "Complex sentences: use connectives (cependant, pourtant, donc, alors que, tandis que) and opinions with justification."],
   example:"Upgrade: 'Je suis allé au cinéma. Le film était bien.'\nAprès avoir fini mes devoirs, je suis allé au cinéma avec mes amis.\nNous avions déjà vu la bande-annonce, donc nous étions impatients.\nBien que le film soit un peu long, je l'ai trouvé passionnant et je le recommanderais à tout le monde.",
   more:[ ex("Replace the object with a pronoun: 'J'ai acheté la robe.'", ["La robe (feminine) → la → l' before the vowel.","In the passé composé the pronoun goes before avoir; the participle agrees with a preceding direct object."], "Je l'ai achetée."),
     ex("Form the pluperfect: 'nous / partir'.", ["Partir takes être → imperfect of être: nous étions.","Participle with plural agreement: partis."], "nous étions partis") ],
   trick:"Pluperfect = one step further back in the past: 'had done'. Imperfect helper + participle.",
   fun:"The subjunctive is used far more in French than in English: 'Il faut que tu viennes!' (You must come!).",
   verbs:["etre","avoir","aller","faire","venir","vouloir","pouvoir","devoir","savoir","prendre","dire","ecrire"],
   pron:["J'avais ('zha-veh') vs j'aurais ('zho-reh'): listen for the vowel.","Je l'ai vu: 'zhuh lay vew'.","J'en ai: 'zhoh(n) nay', with liaison."],
   tasks:[ m(1, "Which tense is 'j'avais fini'?", "pluperfect", ["passé composé", "imperfect", "conditional"], "Imperfect of avoir (j'avais) + participle = pluperfect: I had finished."),
     m(1, "Replace with a pronoun: 'Je regarde la télé.'", "Je la regarde.", ["Je regarde la.", "Je lui regarde.", "La je regarde."], "La télé is a feminine direct object → la, placed before the verb."),
     m(2, "Answer with en: 'Tu as des frères ?' (two)", "Oui, j'en ai deux.", ["Oui, j'y ai deux.", "Oui, je les ai deux.", "Oui, j'ai en deux."], "En replaces de / des + noun, often with a number."),
     m(2, "Choose the correct form: 'Je ___ parle souvent.' (to her)", "lui", ["la", "le", "leur"], "Parler à quelqu'un → indirect object: lui (to him / to her)."),
     m(2, "Which is the conditional of 'être' with 'je'?", "je serais", ["je serai", "j'étais", "je suis été"], "Future stem ser- + imperfect ending -ais = je serais (I would be)."),
     m(2, "Form the pluperfect: 'elle / aller'", "elle était allée", ["elle avait allé", "elle est allée", "elle allait"], "Aller takes être: imperfect of être + participle with agreement: elle était allée."),
     tx(3, "Complete with the subjunctive: 'Bien qu'il ___ difficile, j'aime le français.' (être)", ["soit"], "Bien que (although) takes the subjunctive: qu'il soit."),
     m(3, "Choose the correct sentence: 'I bought the shoes.' → with a pronoun", "Je les ai achetées.", ["Je les ai acheté.", "Je ai les achetées.", "J'ai les achetées."], "Les chaussures (feminine plural) → les before avoir; the participle agrees with a preceding direct object: achetées."),
     m(3, "Which sentence is correct?", "Si j'avais su, je serais venu.", ["Si j'aurais su, je serais venu.", "Si j'avais su, je viendrais hier.", "Si je savais, je serais venu demain."], "Past conditional: si + pluperfect (j'avais su) → conditional perfect (je serais venu)."),
     m(3, "Which connective means 'whereas'?", "tandis que", ["donc", "pourtant", "puisque"], "Tandis que / alors que = whereas. Donc = so, pourtant = however / yet, puisque = since.") ],
   pool:[ m(1, "Which tense is 'je ferais'?", "conditional", ["future", "imperfect", "present"], "Fer- (future stem of faire) + -ais = conditional: I would do."),
     m(2, "Replace with y: 'Nous allons au stade.'", "Nous y allons.", ["Nous allons y.", "Nous en allons.", "Y nous allons."], "Y replaces à + place and goes before the verb."),
     m(2, "Choose: 'Je ___ ai téléphoné hier.' (to them)", "leur", ["les", "lui", "leurs"], "Téléphoner à + people (plural) → leur."),
     m(3, "What does 'pourtant' mean?", "however / yet", ["therefore", "because", "for example"], "Pourtant = however / yet."),
     m(3, "Choose the subjunctive: 'Il faut que tu ___ tes devoirs.' (finir)", "finisses", ["finis", "finiras", "finissais"], "Subjunctive of finir: que tu finisses."),
     m(3, "Translate: 'I had already eaten when he arrived.'", "J'avais déjà mangé quand il est arrivé.", ["J'ai déjà mangé quand il arrivait.", "Je mangeais déjà quand il est arrivé.", "J'avais déjà mangé quand il arrivera."], "Pluperfect for the earlier action (j'avais mangé), passé composé for the event (il est arrivé).") ] })
]};
})(window.UK = window.UK || {});
